<?php declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/credits.php';require_once dirname(__DIR__).'/services/teacher_students.php';$current=tuman_require_role('TEACHER');$db=tuman_database();$students=tuman_teacher_students($db,$current['id']);$v=['assignment_id'=>'','currency_code'=>'INR','payment_date'=>gmdate('Y-m-d'),'amount'=>'','payment_method'=>'CASH','reference_number'=>'','remarks'=>''];$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){foreach($v as $k=>$x)$v[$k]=trim((string)($_POST[$k]??''));try{if(!tuman_csrf_is_valid($_POST['csrf_token']??null))throw new InvalidArgumentException('Your request could not be verified.');$id=filter_var($v['assignment_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)throw new InvalidArgumentException('Choose a student.');tuman_record_advance_credit($db,$current['id'],(int)$id,$v);header('Location: /Tuman/teacher/credits.php');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to record the advance right now.';}}tuman_teacher_page_start('Record advance');?><h1>Record advance</h1><p>Record money received before an invoice is raised. It becomes Student credit that can be applied to a future invoice or refunded.</p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8')?>"><p><label>Student <select name="assignment_id" required><option value="">Choose student</option><?php foreach($students as $s):?><option value="<?=(int)$s['assignment_id']?>"<?=$v['assignment_id']==$s['assignment_id']?' selected':''?>><?=htmlspecialchars(trim($s['first_name'].' '.($s['last_name']??'')),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Currency <select name="currency_code"><?php foreach(TUMAN_CURRENCIES as $code=>$label):?><option value="<?=$code?>"<?=$code===$v['currency_code']?' selected':''?>><?=htmlspecialchars($code.' — '.$label,ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Received date <input type="date" name="payment_date" required value="<?=htmlspecialchars($v['payment_date'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Amount <input name="amount" inputmode="decimal" required value="<?=htmlspecialchars($v['amount'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Method <select name="payment_method"><?php foreach(TUMAN_PAYMENT_METHODS as $m):?><option value="<?=$m?>"<?=$m===$v['payment_method']?' selected':''?>><?=htmlspecialchars(str_replace('_',' ',$m),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Reference <input name="reference_number" maxlength="100" value="<?=htmlspecialchars($v['reference_number'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Remarks <textarea name="remarks" maxlength="500"><?=htmlspecialchars($v['remarks'],ENT_QUOTES,'UTF-8')?></textarea></label></p><p><button>Record advance</button> <a href="/Tuman/teacher/credits.php">Cancel</a></p></form><?php tuman_teacher_page_end(); ?>
